#include<stdio.h>
int main()
{
int arr[5];
int flag=0;
for(int i=0;i<4;i++)
{
scanf("%d",arr[i]);
}
int search_element;
scanf("%d",search_element);
for(int i=0;i<5;i++)
{
if(search_element==arr[i])
{
flag=1;
break;
}

}
if(flag==1)
printf("The element is found");
else
printf("The element is not found");

}
